from collections import deque

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Bidirectional BFS
    def bfs(queue, visited, other_visited, reverse):
        while queue:
            r, c, path = queue.popleft()
            if (r, c) in other_visited:
                # Found a path, combine both paths
                return path + other_visited[(r, c)][1:]
            if grid[r][c] == '#':
                continue
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                    visited[(nr, nc)] = (r, c, path + [(nr, nc)])
                    queue.append((nr, nc, path + [(nr, nc)]))

    # Initialize queues for start and goal BFS
    start_queue = deque()
    goal_queue = deque()
    start_visited = {}
    goal_visited = {}

    start_queue.append((start[0], start[1], [start]))
    goal_queue.append((goal[0], goal[1], [goal]))
    start_visited[(start[0], start[1])] = None
    goal_visited[(goal[0], goal[1])] = None

    # Bidirectional BFS loop
    while start_queue and goal_queue:
        # Expand from start
        path = bfs(start_queue, start_visited, goal_visited, False)
        if path:
            return path
        # Expand from goal
        path = bfs(goal_queue, goal_visited, start_visited, True)
        if path:
            return path

    # No path found
    return []
