                continue
            visited.add(u)
            if u == end:
                return current_dist
            for v, weight in graph[u]:
                if dist[v] > current_dist + weight:
                    dist[v] = current_dist + weight
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Run Dijkstra from both ends
    dist_s = dijkstra(s, t)
    dist_t = dijkstra(t, s)

    # The shortest path is the minimum of the two (since it's undirected in the reverse)
    return min(dist_s, dist_t) if min(dist_s, dist_t) != float('inf') else -1

