import sys

def solve(n, edges, s, t):
    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set distance to self as 0
    for i in range(n):
        dist[i][i] = 0

    # Fill in the direct edges
