from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is valid (within bounds and not a wall)
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    def bidirectional_bfs(start, goal):
        # Queue for forward search from start
        forward_queue = deque([(start, [start])])
        # Queue for backward search from goal
        backward_queue = deque([(goal, [goal])])

        # Visited sets for forward and backward searches
        forward_visited = set([start])
        backward_visited = set([goal])

        while forward_queue and backward_queue:
            # Expand forward search
            for _ in range(len(forward_queue)):
                current, path = forward_queue.popleft()
                if current in backward_visited:
                    # Found a path, return combined path
                    return path + path[::-1][:-1]
                for dr, dc in directions:
                    r, c = current[0] + dr, current[1] + dc
                    if is_valid(r, c) and (r, c) not in forward_visited:
                        forward_visited.add((r, c))
                        forward_queue.append(((r, c), path + [(r, c)]))

            # Expand backward search
            for _ in range(len(backward_queue)):
                current, path = backward_queue.popleft()
                if current in forward_visited:
                    # Found a path, return combined path
                    return path + path[::-1][:-1]
                for dr, dc in directions:
                    r, c = current[0] + dr, current[1] + dc
                    if is_valid(r, c) and (r, c) not in backward_visited:
                        backward_visited.add((r, c))
                        backward_queue.append(((r, c), path + [(r, c)]))

        # If no path is found
        return []

    return bidirectional_bfs(start, goal)

