def solve(n, edges, s, t):
    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Create an array of lists indexed by distance
    # We'll sweep from 0 to max possible distance (100 * 100 = 10000)
    max_dist = 100 * 100  # max possible distance (n=100, w=100)

    # For each distance, keep a list of nodes that can be relaxed
    # This array will be updated as we sweep through distances
    buckets = [[] for _ in range(max_dist + 1)]

    # Initialize the buckets with the starting node
    for v, w in adj[s]:
