                if result:
                    return result
        return None

    # Try BFS first
    path = bfs()
    if path:
        return path

    # If BFS failed, try increasing step DFS
    max_steps = 1
    while True:
        path = dfs_budgeted(start[0], start[1], [start], max_steps)
