                    new_path = path + [(r, c)]
                    queue.append(( (r, c), new_path ))
        return None

    # Run BFS from both ends
    forward_path = bfs(start, goal, True)
    backward_path = bfs(goal, start, False)

    if forward_path:
        return forward_path
    if backward_path:
        return backward_path[::-1]
