from typing import List, Tuple
import sys
sys.setrecursionlimit(10000)

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'  # Only free cells are valid

    def dfs(r: int, c: int, path: List[Tuple[int, int]], depth: int) -> bool:
        if (r, c) == goal:
            return True
        if depth == 0:
            return False
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                path.append((nr, nc))
                if dfs(nr, nc, path, depth - 1):
                    return True
                path.pop()
        return False

    max_depth = max(rows, cols)  # Sufficient upper bound for search
    for depth in range(max_depth + 1):
        path = [start]
        if dfs(start[0], start[1], path, depth):
            return path
    return []
