from typing import List, Tuple
import copy

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def dfs(current, path, max_length):
        if current == goal:
            return path.copy()

        if len(path) >= max_length:
            return None

        row, col = current
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and (new_row, new_col) not in path:
                path.append((new_row, new_col))
                result = dfs((new_row, new_col), path, max_length)
                if result is not None:
                    return result
                path.pop()

        return None

    max_length = 1
    while True:
        path = [start]
        result = dfs(start, path, max_length)
        if result is not None:
            return result
        max_length += 1
        if max_length > rows * cols:
            break

    return []
