    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Bucket sort approach using distance buckets
    buckets = [[] for _ in range(n * 100 + 1)]  # max possible distance is 100 * 100 = 10000
    buckets[0].append(s)

    while buckets:
        # Find the bucket with the smallest distance
        for d in range(len(buckets)):
            if buckets[d]:
                break
        else:
            break  # No more nodes to process

        # Process all nodes in the current bucket
        for u in buckets[d]:
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    # Add v to the bucket corresponding to its new distance
                    buckets[dist[v]].append(v)

        # Clear the current bucket
        buckets[d] = []

    return dist[t] if dist[t] != INF else -1

