            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Run Dijkstra from both ends
    dist_from_s = dijkstra(s, t)
    dist_from_t = dijkstra(t, s)

    # The shortest path from s to t is the minimum of the two directions
    return min(dist_from_s, dist_from_t) if min(dist_from_s, dist_from_t) != float('inf') else -1
