from collections import deque

def solve(n, edges, s, t):
    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles that are reachable from s
    # Use SPFA (Shortest Path Faster Algorithm) for better performance
    # Initialize queue with source node
    in_queue = [False] * n
    queue = deque([s])
    in_queue[s] = True
    cnt = [0] * n
    cnt[s] = 1

    while queue:
        u = queue.popleft()
        in_queue[u] = False
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not in_queue[v]:
                    queue.append(v)
                    in_queue[v] = True
                    cnt[v] += 1
                    if cnt[v] >= n:
                        # Negative cycle detected
                        return -1

    return dist[t] if dist[t] != float('inf') else -1

