def solve(n, edges, s, t):
    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Initialize distance from each node to itself as 0
    for i in range(n):
        dist[i][i] = 0

    # Build adjacency list
