import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(r, c):
        return abs(r - goal[0]) + abs(c - goal[1])

    pq = [(heuristic(*start), 0, start[0], start[1], [start])]
    visited = set()

    while pq:
        _, cost, r, c, path = heapq.heappop(pq)
        if (r, c) == goal:
            return path
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                new_path = path + [(nr, nc)]
                heapq.heappush(pq, (cost + 1 + heuristic(nr, nc), cost + 1, nr, nc, new_path))
    return []
