import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan_distance(pos, goal):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    # Priority queue: (priority, current position, path)
    priority_queue = [(manhattan_distance(start, goal), start, [start])]
    visited = set()

    while priority_queue:
        _, current, path = heapq.heappop(priority_queue)
        r, c = current

        if current == goal:
            return path

        if current in visited:
            continue

        visited.add(current)

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                new_path = path + [(nr, nc)]
                heapq.heappush(priority_queue, (len(new_path) - 1 + manhattan_distance((nr, nc), goal), (nr, nc), new_path))

    return []
