import heapq

def solve(n, edges, s, t):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                return d
            if d > dist[u]:
