import sys

def solve(n, edges, s, t):
    # Initialize distance table with infinity
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set distance to self as 0
    for i in range(n):
        dist[i][i] = 0

    # Fill in direct edges
    for u, v, w in edges:
        if dist[u][v] > w:
            dist[u][v] = w

    # Floyd-Warshall algorithm with three nested loops
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Return the shortest path from s to t or -1 if unreachable
    return dist[s][t] if dist[s][t] != INF else -1
