def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, goal):
        q = deque([(start, [start])])
        visited = set([start])

        while q:
            (r, c), path = q.popleft()
            if (r, c) == goal:
                return path
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append(((nr, nc), path + [(nr, nc)]))
        return []

    # Bidirectional BFS
    forward = deque([start])
    backward = deque([goal])
    forward_visited = set([start])
    backward_visited = set([goal])
    forward_path = {start: [start]}
    backward_path = {goal: [goal]}

