def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) != start

    # Bidirectional BFS
    start_q = deque([start])
    goal_q = deque([goal])

    start_visited = {start: [start]}
    goal_visited = {goal: [goal]}

    while start_q and goal_q:
        # Expand from start
        for _ in range(len(start_q)):
