        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited_start and grid[nr][nc] != '#':
                start_queue.append((nr, nc, dist + 1))

    # BFS from goal
    while goal_queue:
        r, c, dist = goal_queue.popleft()
        if (r, c) in visited_goal:
            continue
        visited_goal.add((r, c))
        goal_dist[(r, c)] = dist
        if grid[r][c] == '#':
