        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited_goal and grid[nr][nc] != '#':
                goal_queue.append((nr, nc, dist + 1))

    # Find the meeting point
    for cell in visited_start:
        if cell in visited_goal:
            meeting_point = cell
            break
    else:
        return []

    # Reconstruct path from start to meeting point
    path = []
    current = meeting_point
    while current != start:
