import heapq

def solve(n, edges, s, t):
    # Build adjacency list and reversed adjacency list
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm with a heap
    def dijkstra(start, adj, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_s = dijkstra(s, adj, n)
    dist_t = dijkstra(t, rev_adj, n)

    for i in range(n):
        if dist_s[i] + dist_t[i] < float('inf'):
            return dist_s[i] + dist_t[i]
    return -1

