        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current: Tuple[int, int], path: List[Tuple[int, int]], depth: int) -> bool:
        if current == goal:
            return True

        if depth == 0:
            return False

        r, c = current
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                new_path = copy.copy(path)
                new_path.append((nr, nc))
                if dfs((nr, nc), new_path, depth - 1):
                    return True
        return False

    # Try depth from 0 to max_possible_depth (rows * cols)
    max_depth = rows * cols
    for depth in range(max_depth + 1):
        path = [start]
        if dfs(start, path, depth):
            return path
    return []
