from typing import List, Tuple
import copy

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(path, depth_limit):
        if path[-1] == goal:
            return path
        if depth_limit == 0:
            return None
        for dr, dc in directions:
            r, c = path[-1]
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                new_path = copy.copy(path)
                new_path.append((nr, nc))
                result = dfs(new_path, depth_limit - 1)
                if result:
                    return result
        return None

    for limit in range(rows * cols + 1):  # max depth limit
        path = [start]
        result = dfs(path, limit)
        if result:
            return result
    return []
