from typing import List, Tuple
import copy

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current: Tuple[int, int], path: List[Tuple[int, int]], steps: int) -> bool:
        r, c = current
        if current == goal:
            return True
        if steps >= len(path) + 1:
            return False

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                new_path = path + [(nr, nc)]
                if dfs((nr, nc), new_path, steps):
                    return True
        return False

    max_steps = 1
    while True:
        path = [start]
        if dfs(start, path, max_steps):
            return path
        max_steps += 1
